static inline int smart_io_q_tree_predict(const int state_q[SMART_IO_Q_TREE_STATE_DIM])
{
	int node_index = 0;
	int depth;

	if (!state_q)
		return SMART_IO_Q_TREE_NO_BASELINE;
	for (depth = 0; depth <= SMART_IO_Q_TREE_MAX_DEPTH; ++depth) {
		const struct smart_io_q_tree_node *node = &smart_io_q_tree_nodes[node_index];

		if (node->feature < 0)
			return node->action_id;
		node_index = state_q[node->feature] <= node->threshold ? node->left : node->right;
	}
	return SMART_IO_Q_TREE_NO_BASELINE;
}

